import test from 'node:test';import assert from 'node:assert/strict';import {readFileSync} from 'node:fs';import {verifyLearningGoalsRelease} from './check-learning-goals-release-20261101.mjs';
void test('approved goals, labels, scope and local proof pass',()=>assert.equal(verifyLearningGoalsRelease().approvedBy,'Nico'));
for(const file of ['data/klink-learning-goals.json','components/product/package-exercise-browser.tsx'])void test('reject modified source '+file,()=>assert.throws(()=>verifyLearningGoalsRelease(f=>f===file?Buffer.concat([readFileSync(f),Buffer.from(' ') ]):readFileSync(f))));
for(const[file,alter]of[['docs/klink-owner-release-learning-goals-20261101.json',r=>({...r,publicationApproved:false})],['docs/learning-goals-20261101/local/browser/checks.json',r=>({...r,checks:r.checks.slice(1)})],['docs/learning-goals-20261101/backup.json',r=>({...r,fullReadback:false})]])void test('reject invalid proof '+file,()=>assert.throws(()=>verifyLearningGoalsRelease(f=>f===file?Buffer.from(JSON.stringify(alter(JSON.parse(readFileSync(f))))):readFileSync(f))));
